import React, { Component } from 'react';
import './googlemap.css';
import AudioPlayer from 'react-h5-audio-player';
import 'react-h5-audio-player/lib/styles.css';

/* global google */

class Map extends Component {
    constructor(props) {
        super(props);
        this.state = {
            selectedTime: '',
            currentTimestamp: "",
            petLocations: [],
            playing: false,
            currentPointIndex: 0,
            intervalId: null,
            currentPhoto: null,
            mapLoaded: false,
            view: 'main',
            showtrack: false,
            petLocation: null,
            petName: 'Bella',
            locationName: '',
            markers: [],
            polylines: [],
        };
        this.map = null;
        this.panorama = null;
    }

    componentDidMount() {
        this.loadScript();
    }

    componentWillUnmount() {
        const script = document.getElementById('googleMaps');
        if (script) {
            document.head.removeChild(script);
        }
        if (this.state.intervalId) {
            clearInterval(this.state.intervalId);
        }
    }

    loadScript = () => {
        const existingScript = document.getElementById('googleMaps');
        if (!existingScript) {
            const script = document.createElement('script');
            script.src = "https://maps.googleapis.com/maps/api/js?key=AIzaSyB5t8KXIpcdx0n3I7FtsVtCJ86YoDngaYw&libraries=places,directions&callback=initMap";
            script.id = 'googleMaps';
            script.async = true;
            script.defer = true;
            window.initMap = this.initMap;
            document.head.appendChild(script);
        } else {
            this.initMap();
        }
    };

    initMap = () => {
        if (typeof google !== 'undefined' && google.maps) {
            this.fetchData();
        } else {
            console.error("Google Maps JavaScript API not loaded.");
        }
    };

    fetchData = () => {
        fetch('http://localhost:3001/trackipetmap', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ pet_id: 1 }),
        })
            .then((response) => response.json())
            .then((data) => {
                const { lat, lng, locationName } = data;
                this.map = new window.google.maps.Map(document.getElementById('map'), {
                    zoom: 20,
                    center: { lat, lng },
                });

                const marker = new window.google.maps.Marker({
                    position: { lat, lng },
                    map: this.map,
                    title: 'Pet Location',
                });

                this.setState({ petLocation: { lat, lng }, locationName, markers: [marker], mapLoaded: true });
                console.log(`Pet location: ${lat}, ${lng}`);
            })
            .catch((error) => console.error('Error fetching location:', error));
    };

    handleTimeChange = (event) => {
        const selectedTime = event.target.value;
        this.setState({ selectedTime });
    };

    formatDate = (date) => {
        const pad = (n) => n < 10 ? '0' + n : n;
        return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
    };

    calculateTime = (selectedTime) => {
        const now = new Date();
        let timePoints = [];

        const hours = parseInt(selectedTime);
        if (!isNaN(hours)) {
            for (let i = 0; i <= hours; i++) {
                const time = new Date(now.getTime() - i * 60 * 60 * 1000);
                timePoints.push(this.formatDate(time));
            }
        } else {
            switch (selectedTime) {
                case 'day':
                    for (let i = 0; i <= 24; i++) {
                        const time = new Date(now.getTime() - i * 60 * 60 * 1000);
                        timePoints.push(this.formatDate(time));
                    }
                    break;
                case 'week':
                    for (let i = 0; i <= 7 * 24; i++) {
                        const time = new Date(now.getTime() - i * 60 * 60 * 1000);
                        timePoints.push(this.formatDate(time));
                    }
                    break;
            }
        }
        return timePoints;
    };

    showHistory = () => {
        const { selectedTime } = this.state;
        debugger;
        if (!selectedTime) {
            alert('Please select a time period.');
            return;
        }

        const pastTime = this.calculateTime(selectedTime);

        this.setState({ currentTimestamp: this.formatDate(pastTime) }, () => {
            fetch(`http://localhost:3001/locationhistory?pet_id=1&time=${encodeURIComponent(pastTime.toISOString())}`)
                .then((response) => {
                    if (!response.ok) {
                        return response.text().then(text => { throw new Error(text); });
                    }
                    return response.json();
                })
                .then((data) => {
                    const filteredData = data.filter(point => new Date(point.timestamp) >= pastTime);
                    console.log("filterdata:",filteredData);
                    this.setState({
                        petLocations: filteredData,
                        currentPointIndex: 0,
                        currentPhoto: null,
                        showtrack: true
                    }, this.initPanorama);
                })

                .catch((error) => {
                    console.error('Error fetching location history:', error);
                    console.error('Fetch response: ', error.message);
                });
        });
    };

    initPanorama = () => {
        const { petLocation } = this.state;
        if (!petLocation) {
            console.error('Pet location not available.');
            return;
        }

        this.panorama = new window.google.maps.StreetViewPanorama(
            document.getElementById('pano'),
            {
                position: petLocation,
                pov: {
                    heading: 34,
                    pitch: 10,
                },
            }
        );
        this.map.setStreetView(this.panorama);
    };

    playHistory = () => {
        if (!this.state.playing) {
            const intervalId = setInterval(() => {
                const { currentPointIndex, petLocations } = this.state;
                if (currentPointIndex >= petLocations.length) {
                    clearInterval(this.state.intervalId);
                    this.setState({ playing: false });
                    return;
                }

                const point = petLocations[currentPointIndex];
                const previousPoint = currentPointIndex > 0 ? petLocations[currentPointIndex - 1] : null;
                this.addMarkerAndLine(point, previousPoint);
                const timestamp = new Date(point.timestamp);
                this.setState({
                    currentPointIndex: currentPointIndex + 1,
                    currentTimestamp: this.formatDate(timestamp)
                });
                this.updatePanorama(point);
            }, 10000); // 10 seconds

            this.setState({ intervalId, playing: true });
        }
    };

    stopHistory = () => {
        if (this.state.intervalId) {
            clearInterval(this.state.intervalId);
            this.setState({ playing: false, intervalId: null });
        }
    };

    addMarkerAndLine = (point, previousPoint) => {
        const { petLocations, currentPointIndex } = this.state;
        const petLocation = petLocations[currentPointIndex];
        const marker = new window.google.maps.Marker({
            position: { lat: parseFloat(point.latitude), lng: parseFloat(point.longitude) },
            map: this.map,
            title: `Pet Location at ${this.formatDate(new Date(point.timestamp))}`,
        });

        this.setState((prevState) => ({
            markers: [...prevState.markers, marker]
        }));

        if (previousPoint) {
            const line = new window.google.maps.Polyline({
                path: [
                    { lat: parseFloat(previousPoint.latitude), lng: parseFloat(previousPoint.longitude) },
                    { lat: parseFloat(point.latitude), lng: parseFloat(point.longitude) },
                ],
                geodesic: true,
                strokeColor: '#FF0000',
                strokeOpacity: 1.0,
                strokeWeight: 2,
            });
            line.setMap(this.map);
            this.setState((prevState) => ({
                polylines: [...prevState.polylines, line]
            }));
        }

        this.updatePanorama(point);

        const service = new window.google.maps.places.PlacesService(this.map);
        const request = {
            location: new window.google.maps.LatLng(point.latitude, point.longitude),
            radius: '50'
        };

        service.nearbySearch(request, (results, status) => {
            if (status === window.google.maps.places.PlacesServiceStatus.OK && results.length > 0) {
                const place = results[0];
                console.log('Nearby search results:', results);
                const photoUrl = place.photos && place.photos.length > 0
                    ? place.photos[0].getUrl({ maxWidth: 100, maxHeight: 100 })
                    : '';

                if (photoUrl) {
                    console.log('Photo URL:', photoUrl);
                } else {
                    console.log('No photo available for this location.');
                }
                const localTime = new Date(petLocation.timestamp);
                console.log(localTime);
                this.setState({
                    currentPhoto: {
                        name: place.name,
                        lat: point.latitude,
                        lng: point.longitude,
                        photoUrl: photoUrl,
                        timestamp: localTime.toISOString()
                    }
                });

                if (window.google.maps.StreetViewService) {
                    const streetViewService = new window.google.maps.StreetViewService();
                    const STREETVIEW_MAX_DISTANCE = 50;

                    streetViewService.getPanorama({
                        location: new window.google.maps.LatLng(point.latitude, point.longitude),
                        radius: STREETVIEW_MAX_DISTANCE
                    }, this.processStreetViewData);
                } else {
                    console.error('StreetViewService is not available.');
                }
            } else {
                console.error('Nearby search failed or no photos available:', status);
            }
        });
    };

    updatePanorama = (point) => {
        if (this.panorama) {
            this.panorama.setPosition({ lat: parseFloat(point.latitude), lng: parseFloat(point.longitude) });
        }
    };

    processStreetViewData = (data, status) => {
        if (status === window.google.maps.StreetViewStatus.OK) {
            this.panorama.setPosition(data.location.latLng);
            this.panorama.setPov({
                heading: 34,
                pitch: 10,
            });
        } else {
            console.error('Street View data not found for this location.');
        }
    };

    setView = (view) => {
        this.setState({ view }, () => {
            if (view === 'main') {
                this.stopHistory();
                this.clearMarkersAndPolylines();
                this.fetchData();
            }
        });
    };

    clearMarkersAndPolylines = () => {
        this.state.markers.forEach(marker => marker.setMap(null));
        this.state.polylines.forEach(polyline => polyline.setMap(null));
        this.setState({ markers: [], polylines: [] });
    };

    openDirections = () => {
        const { petLocation } = this.state;
        if (petLocation) {
            if (navigator.geolocation) {
                navigator.geolocation.getCurrentPosition((position) => {
                    const origin = `${position.coords.latitude},${position.coords.longitude}`;
                    const destination = `${petLocation.lat},${petLocation.lng}`;
                    const directionsUrl = `https://www.google.com/maps/dir/?api=1&origin=${origin}&destination=${destination}&travelmode=driving`;
                    window.open(directionsUrl, '_blank');
                });
            } else {
                alert('Geolocation is not supported by this browser.');
            }
        } else {
            alert('Pet location not available.');
        }
    };

    renderSidebarMain = () => (
        <div className="sidebar">
            <button className="petName" onClick={() => this.setView('details')}>{this.state.petName}</button>
            <button className="add-microchip-button" onClick={() => alert('Add Microchip clicked')}>Add Microchip</button>
        </div>
    );

    renderSidebarDetails = () => (
        <div className="sidebar">
            <button onClick={() => this.setView('main')} className="back-button">&larr;</button>
            <button className="show1" onClick={this.openDirections}>Pet Location</button>
            <button className="show2" onClick={() => this.setView('track')}>Pet Track</button>
        </div>
    );

    renderSidebarTrack = () => (
        <div className="sidebar">
            <button onClick={() => this.setView('details')} className="back-button">&larr;</button>
            <select onChange={this.handleTimeChange} value={this.state.selectedTime}>
                <option value="">Select Time Period</option>
                {Array.from({ length: 24 }, (_, i) => (
                    <option key={i + 1} value={i + 1}>{`Last ${i + 1} hours`}</option>
                ))}
                <option value="day">Last Day</option>
                <option value="week">Last Week</option>
            </select>
            <button className='show2' onClick={this.showHistory}>Show History</button>
            {this.state.currentTimestamp && (
                <div className="timestamp-container">
                    <h4>{this.state.currentTimestamp}</h4>
                </div>
            )}
        </div>
    );

    renderSidebar = () => {
        const { view } = this.state;
        if (view === 'main') return this.renderSidebarMain();
        if (view === 'details') return this.renderSidebarDetails();
        if (view === 'track') return this.renderSidebarTrack();
        return null;
    };

    render() {
        const { currentPhoto, mapLoaded, showtrack, view } = this.state;
        console.log("Current Photo:", currentPhoto);
        console.log("Map Loaded:", mapLoaded);

        return (
            <div className="app-container">
                <div className="content-container-2">
                    {this.renderSidebar()}
                    <div id="map" className="map-container"></div>
                    {view === 'track' && (
                        <>
                            <div id="pano" className="map-streetview-container"></div>
                            {currentPhoto && currentPhoto.photoUrl && (
                                <div className="map-photo-container">
                                    <img src={currentPhoto.photoUrl} alt={currentPhoto.name} className="small-photo" />
                                    <h3>{currentPhoto.name}</h3>
                                    <p>Latitude: {currentPhoto.lat}</p>
                                    <p>Longitude: {currentPhoto.lng}</p>
                                    <p>Timestamp: {this.formatDate(new Date(currentPhoto.timestamp))}</p>
                                </div>
                            )}
                            {mapLoaded && showtrack && (
                                <div className="audio-player-overlay">
                                    <AudioPlayer
                                        src="URL_OF_YOUR_AUDIO_FILE"
                                        onPlay={this.playHistory}
                                        onPause={this.stopHistory}
                                        showJumpControls={false}
                                        customAdditionalControls={[]}
                                    />
                                </div>
                            )}
                        </>
                    )}
                </div>
            </div>
        );
    }
}

export default Map;



